// Generates docs/RULES.md from the built-in rule catalogue (the same data as `devgu rules explain`).
import { writeFile } from "node:fs/promises";
import { ruleCatalog } from "../packages/core/dist/index.js";

const rules = ruleCatalog();
const out = [
  "# DEVGU rule catalogue",
  "",
  "Generated by `npm run docs:rules`. Do not edit by hand. Every rule lists what it cannot detect.",
  "",
  "| Rule | Severity | Confidence | Engine | Name |",
  "|---|---|---|---|---|",
  ...rules.map(
    (r) =>
      `| [${r.id}](#${r.id.toLowerCase()}) | ${r.severity} | ${r.confidence} | ${r.engine} | ${r.name} |`,
  ),
  "",
];
for (const r of rules) {
  out.push(`## ${r.id}`, "", `**${r.name}**`, "", r.description, "");
  out.push(
    `- Category: ${r.category}`,
    `- Default severity: ${r.severity}`,
    `- Default confidence: ${r.confidence}`,
    "",
  );
  out.push(`**Remediation:** ${r.remediation}`, "", `**Limitations:** ${r.limitations}`, "");
  if (r.references.length) out.push("References:", "", ...r.references.map((x) => `- ${x}`), "");
}
await writeFile(new URL("../docs/RULES.md", import.meta.url), out.join("\n"));
console.log(`Wrote docs/RULES.md (${rules.length} rules)`);
